const literature = ref<Entity[]>([]), ideas = ref<Entity[]>([]), memories = ref<Entity[]>([]), experiments = ref<Entity[]>([]), manuscripts = ref<Entity[]>([]), reviews = ref<Entity[]>([]), comments = ref<Entity[]>([]), versions = ref<Entity[]>([])
