const importing = ref(false), versionDiff = ref('')
const agents = ref<Entity[]>([]), workflows = ref<Entity[]>([]), moduleAgentRunning = ref(false), moduleWorkflowRunning = ref(false), moduleRunResult = ref(''), moduleRunStatus = ref('')
const moduleAgentIds = reactive<Record<string,string>>({}), moduleWorkflowIds = reactive<Record<string,string>>({})
const moduleAgentPrompts = reactive<Record<string,string>>({ literature:'请根据本项目研究问题，建议下一步文献调研重点与检索策略。', frontier:'请追踪本项目近三年的领域前沿，解释热点、上升主题、证据范围与趋势限制。', ideas:'请与我一起澄清一个研究 Idea，并提出一个最关键的问题。', assets:'请检查当前研究假设如何转化为可复现的实验方案。', data:'请检查科研数据质量，并为核心论点建议诚实、可发表的论文图表。', writing:'请检查当前论文最需要优先改进的结构或论证问题。', review:'请从委员会主席角度制定本轮审稿标准与风险检查清单。' })
const defaultAgentSlugs:Record<string,string> = { literature:'research-literature-specialist', frontier:'research-frontier-tracker', ideas:'research-idea-mentor', assets:'research-experiment-specialist', data:'research-data-figure-specialist', writing:'research-latex-writing-specialist', review:'research-review-chair' }
