const previewZoom = ref(1), previewFullscreen = ref(false), imageViewer = reactive({show:false,src:'',alt:'',zoom:1,rotation:0,fit:true})
const reviewProgress = ref<Entity[]>([]), reviewRunning = ref(false), reviewStage = ref('等待开始')
