async function loadProject() { project.value = await api.get(`/research-projects/${projectId.value}`) }
async function loadModuleCatalog(){
  [agents.value,workflows.value]=await Promise.all([api.get('/agents'),api.get('/workflows')])
  const savedAgents=project.value.settings?.module_agents||{}, savedWorkflows=project.value.settings?.module_workflows||{}
  for(const module of Object.keys(defaultAgentSlugs)){
    moduleAgentIds[module]=savedAgents[module]||agents.value.find(item=>item.slug===defaultAgentSlugs[module])?.id||''
    moduleWorkflowIds[module]=savedWorkflows[module]||''
  }
}
async function saveModuleAssignments(){
  const settings={...(project.value.settings||{}),module_agents:{...moduleAgentIds},module_workflows:{...moduleWorkflowIds}}
  project.value=await api.patch(`/research-projects/${projectId.value}`,{settings});store.notify('模块专家与工作流配置已保存')
}
async function runModuleAgent(){
  const agentId=moduleAgentIds[tab.value];if(!agentId)return store.notify('请先选择模块 Agent','error')
  moduleAgentRunning.value=true;moduleRunResult.value=''
  try{const result=await api.post<Entity>(`/agents/${agentId}/run`,{input:moduleAgentPrompts[tab.value],context:{project_id:projectId.value,module:tab.value,project_name:project.value.name}});moduleRunResult.value=result.output_text||'Agent 已完成，但未返回文本结果。'}catch(error:any){store.notify(error.message,'error')}finally{moduleAgentRunning.value=false}
}
async function runModuleWorkflow(){
  const workflowId=moduleWorkflowIds[tab.value];if(!workflowId)return store.notify('请先选择已有工作流','error')
  moduleWorkflowRunning.value=true;moduleRunStatus.value='正在连接工作流…';moduleRunResult.value=''
  try{await api.streamEvents(`/workflows/${workflowId}/run/stream`,{input:{task:moduleAgentPrompts[tab.value],project_id:projectId.value,project_name:project.value.name,module:tab.value},security_profile:'read_only',permission_mode:'inherit'},event=>{
    if(event.type==='step')moduleRunStatus.value=event.step?.message||event.step?.type||'工作流运行中'
    if(event.type==='workflow_result'){moduleRunStatus.value=`工作流已完成 · ${event.run?.status||'completed'}`;moduleRunResult.value=event.run?.output_text||event.run?.result||'工作流结果已保存，可前往工作流页面查看。'}
    if(event.type==='error')throw new Error(event.message)
  })}catch(error:any){store.notify(error.message,'error');moduleRunStatus.value='工作流执行失败'}finally{moduleWorkflowRunning.value=false}
}
async function loadSection() {
  loading.value = true
  try {
    if (tab.value==='literature') literature.value = await api.get(`/research-projects/${projectId.value}/literature`)
    if (tab.value==='frontier') { frontierSnapshots.value=await api.get(`/research-projects/${projectId.value}/frontier`); frontierSnapshot.value=frontierSnapshots.value[0]?.payload||null }
    if (tab.value==='ideas') ideas.value = await api.get(`/research-projects/${projectId.value}/ideas`)
    if (tab.value==='assets') [memories.value,experiments.value] = await Promise.all([api.get(`/research-projects/${projectId.value}/memories`),api.get(`/research-projects/${projectId.value}/experiments`)])
    if (tab.value==='data') { dataAssets.value=await api.get(`/research-projects/${projectId.value}/data-assets`); selectedDatasetId.value ||= datasets.value[0]?.id||''; const latest=publicationFigures.value[0]; figureResult.value=latest?{id:latest.id,title:latest.title,...latest.payload}:null }
    if (['writing','review'].includes(tab.value)) { manuscripts.value = await api.get(`/research-projects/${projectId.value}/manuscripts`); if (!selectedManuscriptId.value && manuscripts.value[0]) await selectManuscript(manuscripts.value[0].id) }
    if (tab.value==='review') reviews.value = await api.get(`/research-projects/${projectId.value}/reviews`)
  } finally { await loadProject(); loading.value=false }
}
async function heartbeat() { try { await api.put(`/research-projects/${projectId.value}/presence`, { page:tab.value, cursor:selectedManuscriptId.value?{manuscript_id:selectedManuscriptId.value}:{} }); presence.value = await api.get(`/research-projects/${projectId.value}/presence`) } catch {} }
