async function createInvite(){try{const invite=await api.post<Entity>(`/research-projects/${projectId.value}/invites`,inviteForm);inviteCode.value=invite.code;ledger.value=await api.get(`/research-projects/${projectId.value}/ledger`);store.notify('协作邀请码已生成')}catch(error:any){store.notify(error.message,'error')}}
async function copyInvite(){if(!inviteCode.value)return;await navigator.clipboard.writeText(inviteCode.value);store.notify('邀请码已复制')}
async function openResources() {
  const [bound,agents,bases,workflows,skills] = await Promise.all([
    api.get<Entity[]>(`/research-projects/${projectId.value}/resources`), api.get<Entity[]>('/agents'), api.get<Entity[]>('/knowledge-bases'), api.get<Entity[]>('/workflows'), api.get<Entity[]>('/skills?verified_only=true'),
  ])
  resources.value=bound; resourceCatalog.agent=agents; resourceCatalog.knowledge_base=bases; resourceCatalog.workflow=workflows; resourceCatalog.skill=skills; showResources.value=true
}
async function addResource() {
  if(!resourceForm.resource_id)return store.notify('请选择需要绑定的系统资源','error')
  const selected=currentResourceOptions.value.find(item=>item.id===resourceForm.resource_id)
  await api.post(`/research-projects/${projectId.value}/resources`,{...resourceForm,label:resourceForm.label||selected?.name||'',metadata:{bound_from:'research_ui'}})
  resourceForm.resource_id='';resourceForm.label='';await openResources();store.notify('资源已加入科研项目')
}
async function searchLiterature() { thinking.value=true; try { const rows=await api.post<Entity[]>(`/research-projects/${projectId.value}/literature/search`,searchForm); literature.value=[...rows,...literature.value]; await loadProject(); store.notify(`新增 ${rows.length} 篇候选文献`) } catch(error:any){store.notify(error.message,'error')} finally{thinking.value=false} }
async function setLiteratureStatus(item:Entity,status:string) { item.status=status; await api.patch(`/research-projects/${projectId.value}/literature/${item.id}`,{title:item.title,authors:item.authors,year:item.year,doi:item.doi,url:item.url,source:item.source,abstract:item.abstract,status,credibility:item.credibility,tags:item.tags||[],notes:item.notes||''}) }
async function synthesize() { thinking.value=true; try { synthesis.value=(await api.post<Entity>(`/research-projects/${projectId.value}/literature/synthesize`)).content } catch(error:any){store.notify(error.message,'error')} finally{thinking.value=false} }
async function generateAcademicFigure(){thinking.value=true;try{academicFigure.value=(await api.post<Entity>(`/research-projects/${projectId.value}/literature/figure`)).figure}catch(error:any){store.notify(error.message,'error')}finally{thinking.value=false}}
async function trackFrontier(){frontierBusy.value=true;try{frontierSnapshot.value=await api.post<Entity>(`/research-projects/${projectId.value}/frontier/track`,frontierForm);frontierSnapshots.value=await api.get(`/research-projects/${projectId.value}/frontier`);store.notify(`已用 ${frontierSnapshot.value.sources?.length||0} 篇可追溯文献更新前沿快照`)}catch(error:any){store.notify(error.message||'前沿追踪失败','error')}finally{frontierBusy.value=false}}
async function uploadDataset(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;dataBusy.value=true;try{const created=await api.upload<Entity>(`/research-projects/${projectId.value}/data-assets/upload`,file);await loadSection();selectedDatasetId.value=created.id;store.notify(`已分析 ${created.profile.rows} 行、${created.fields.length} 个字段`)}catch(error:any){store.notify(error.message||'科研数据导入失败','error')}finally{dataBusy.value=false;input.value=''}}
async function generatePublicationFigure(){if(!selectedDatasetId.value)return store.notify('请先选择科研数据集','error');dataBusy.value=true;try{figureResult.value=await api.post<Entity>(`/research-projects/${projectId.value}/figures`,{dataset_id:selectedDatasetId.value,...figureForm});dataAssets.value=await api.get(`/research-projects/${projectId.value}/data-assets`);store.notify('论文图表已通过质量门禁并生成矢量 SVG')}catch(error:any){store.notify(error.message||'论文图表生成失败','error')}finally{dataBusy.value=false}}
async function deleteDataAsset(item:Entity){if(!confirm(`删除“${item.title}”？`))return;try{await api.delete(`/research-projects/${projectId.value}/data-assets/${item.id}`);if(selectedDatasetId.value===item.id)selectedDatasetId.value='';await loadSection();store.notify('数据资产已删除')}catch(error:any){store.notify(error.message,'error')}}
function downloadFigure(figure:Entity){const blob=new Blob([String(figure.svg||'')],{type:'image/svg+xml;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`${String(figure.title||'publication-figure').replace(/[\\/:*?"<>|]/g,'-')}.svg`;link.click();URL.revokeObjectURL(url)}
async function sendIdea() { if(!ideaInput.value.trim()||thinking.value)return; const text=ideaInput.value; ideaMessages.value.push({role:'user',content:text}); ideaInput.value=''; thinking.value=true; try { const result=await api.post<Entity>(`/research-projects/${projectId.value}/ideas/chat`,{message:text,history:ideaMessages.value.slice(-30),agent_id:moduleAgentIds.ideas||null}); ideaMessages.value.push({role:'assistant',content:result.answer}) } catch(error:any){store.notify(error.message,'error')} finally{thinking.value=false} }
function resetIdeaForm(){Object.assign(ideaForm,{title:'',problem:'',hypothesis:'',novelty:'',method:'',status:'exploring',evidence:[],scores:{}});selectedIdea.value=null}
function openIdea(item:Entity,mode:'view'|'edit'='view'){selectedIdea.value=item;ideaPanelMode.value=mode;Object.assign(ideaForm,{title:item.title,problem:item.problem||'',hypothesis:item.hypothesis||'',novelty:item.novelty||'',method:item.method||'',status:item.status||'exploring',evidence:item.evidence||[],scores:item.scores||{}});showIdeaPanel.value=true}
async function saveIdea() { if(!ideaForm.title.trim())return store.notify('请填写 Idea 名称','error');savingIdea.value=true;try{if(selectedIdea.value){const updated=await api.patch<Entity>(`/research-projects/${projectId.value}/ideas/${selectedIdea.value.id}`,ideaForm);const index=ideas.value.findIndex(item=>item.id===updated.id);if(index>=0)ideas.value[index]=updated;store.notify('Idea 已更新')}else{const created=await api.post<Entity>(`/research-projects/${projectId.value}/ideas`,ideaForm);ideas.value.unshift(created);store.notify('Idea 已保存')}await loadProject();showIdeaPanel.value=false;resetIdeaForm()}catch(error:any){store.notify(error.message,'error')}finally{savingIdea.value=false} }
async function deleteIdea(item:Entity){if(!confirm(`删除 Idea“${item.title}”？此操作不可撤销。`))return;try{await api.delete(`/research-projects/${projectId.value}/ideas/${item.id}`);ideas.value=ideas.value.filter(entry=>entry.id!==item.id);if(selectedIdea.value?.id===item.id){showIdeaPanel.value=false;resetIdeaForm()}await loadProject();store.notify('Idea 已删除')}catch(error:any){store.notify(error.message,'error')}}
async function adoptIdea(item:Entity){const experiment=await api.post<Entity>(`/research-projects/${projectId.value}/ideas/${item.id}/experiment`);item.status='adopted';await loadProject();store.notify(`已创建实验“${experiment.title}”`)}
async function saveMemory() { await api.post(`/research-projects/${projectId.value}/memories`,memoryForm); memoryForm.content=''; await loadSection() }
async function createSkill() { const selected=memories.value.filter(item=>item.locked); if(!selected.length)return store.notify('请先锁定至少一条已确认记忆','error'); await api.post(`/research-projects/${projectId.value}/skills`,{name:`${project.value.name}科研方法`,description:'由项目已确认记忆生成，需在扩展与模型中完成验证后启用。',memory_ids:selected.map(item=>item.id)}); store.notify('Skill 草稿已生成，当前为待验证且禁用状态') }
async function saveExperiment() { await api.post(`/research-projects/${projectId.value}/experiments`,experimentForm); experimentForm.title=''; await loadSection() }
async function updateExperiment(item:Entity){await api.patch(`/research-projects/${projectId.value}/experiments/${item.id}`,{status:item.status,result:item.result||{},design:item.design||{}});store.notify('实验记录已更新')}
async function createManuscript() { const item=await api.post<Entity>(`/research-projects/${projectId.value}/manuscripts`,manuscriptForm); manuscriptForm.title=''; manuscripts.value.unshift(item); await selectManuscript(item.id); await loadProject() }
async function selectManuscript(id:string) { selectedManuscriptId.value=id; const manuscript=await api.get<Entity>(`/research-projects/${projectId.value}/manuscripts/${id}`); currentManuscript.value=manuscript; selectedFilePath.value=manuscript.main_file||Object.keys(manuscript.files||{})[0]||'main.tex'; preview.value=manuscript.preview; versionDiff.value=''; [comments.value,versions.value]=await Promise.all([api.get(`/research-projects/${projectId.value}/comments?manuscript_id=${id}`),api.get(`/research-projects/${projectId.value}/manuscripts/${id}/versions`)]) }
async function saveManuscript() { const manuscript=currentManuscript.value; if(!manuscript)return; try { const saved=await api.put<Entity>(`/research-projects/${projectId.value}/manuscripts/${manuscript.id}`,{content:manuscript.files?.[manuscript.main_file]?.content||manuscript.content,bibliography:manuscript.bibliography||'',main_file:manuscript.main_file,files:manuscript.files,base_version:manuscript.version,change_summary:saveSummary.value}); const refreshed=await api.get<Entity>(`/research-projects/${projectId.value}/manuscripts/${saved.id}`); currentManuscript.value=refreshed; saveSummary.value=''; preview.value=refreshed.preview; versions.value=await api.get(`/research-projects/${projectId.value}/manuscripts/${saved.id}/versions`); store.notify(`已保存版本 ${saved.version}`) } catch(error:any){store.notify(error.message,'error'); if(error.status===409) await selectManuscript(manuscript.id)} }
async function importManuscript(event:Event,folder=false){const input=event.target as HTMLInputElement;const files=Array.from(input.files||[]);if(!files.length)return;importing.value=true;try{const paths=files.map(file=>folder?((file as File&{webkitRelativePath?:string}).webkitRelativePath||file.name):file.name);const item=await api.uploadFiles<Entity>(`/research-projects/${projectId.value}/manuscripts/import`,files,{},paths);manuscripts.value.unshift(item);await selectManuscript(item.id);await loadProject();store.notify(`已导入 ${Object.keys(item.files||{}).length} 个 LaTeX 项目文件`)}catch(error:any){store.notify(error.message,'error')}finally{importing.value=false;input.value=''}}
type NativeSelectedFile={name:string;relative_path:string;content_base64:string}
function nativeRecord(file:NativeSelectedFile){
  const extension=file.relative_path.toLowerCase().split('.').pop()||''
  const textExtensions=new Set(['tex','bib','cls','sty','bst','bbx','cbx','cfg','def','clo','txt','md','csv','tsv'])
  const mime:Record<string,string>={tex:'text/x-tex',bib:'text/x-bibtex',png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',pdf:'application/pdf',eps:'application/postscript',svg:'image/svg+xml'}
  if(textExtensions.has(extension)){
    const bytes=Uint8Array.from(atob(file.content_base64),char=>char.charCodeAt(0))
    return{content:new TextDecoder('utf-8').decode(bytes),encoding:'utf8',mime:mime[extension]||'text/plain',size:bytes.length}
  }
  return{content:file.content_base64,encoding:'base64',mime:mime[extension]||'application/octet-stream',size:Math.floor(file.content_base64.length*0.75)}
}
function nativeFilesToUploads(selected:NativeSelectedFile[]){return selected.map(file=>{const bytes=Uint8Array.from(atob(file.content_base64),char=>char.charCodeAt(0));return new File([bytes],file.name)})}
async function pickNativeProject(folder=false){
  if(!('__TAURI_INTERNALS__' in window)){(folder?folderInput:importInput).value?.click();return}
  importing.value=true
  try{
    const selected=await invoke<NativeSelectedFile[]>(folder?'select_latex_folder':'select_latex_files')
    if(!selected.length)return
    const uploads=nativeFilesToUploads(selected)
    const item=await api.uploadFiles<Entity>(`/research-projects/${projectId.value}/manuscripts/import`,uploads,{},selected.map(file=>file.relative_path))
    manuscripts.value.unshift(item);await selectManuscript(item.id);await loadProject();store.notify(`已导入 ${Object.keys(item.files||{}).length} 个 LaTeX 项目文件`)
  }catch(error:any){store.notify(error.message||String(error),'error')}finally{importing.value=false}
}
async function addNativeResources(){
  const manuscript=currentManuscript.value;if(!manuscript)return store.notify('请先选择一篇论文','error')
  try{
    const selected='__TAURI_INTERNALS__' in window?await invoke<NativeSelectedFile[]>('select_latex_files'):[]
    if(!selected.length){importInput.value?.click();return}
    const missing=preview.value?.missing_resources||[]
    const addedPaths:string[]=[]
    for(const file of selected){const raw=file.relative_path.replace(/\\/g,'/').replace(/^\/+/, '');const basename=raw.split('/').pop();const expected=missing.find((path:string)=>path.split('/').pop()===basename);const path=expected||raw;manuscript.files[path]=nativeRecord(file);addedPaths.push(path)}
    selectedFilePath.value=addedPaths[0]
    store.notify(`已添加 ${selected.length} 个资源；保存版本后正式进入协作历史`)
  }catch(error:any){store.notify(error.message||String(error),'error')}
}
function addProjectFile(){if(!currentManuscript.value)return;const raw=prompt('输入项目内相对路径，例如 sections/method.tex 或 references.bib');if(!raw)return;const path=raw.replace(/\\/g,'/').replace(/^\/+/, '');if(path.includes('..')||currentManuscript.value.files[path])return store.notify('路径无效或文件已存在','error');currentManuscript.value.files[path]={content:'',encoding:'utf8',mime:path.endsWith('.bib')?'text/x-bibtex':'text/x-tex',size:0};selectedFilePath.value=path}
function deleteProjectFile(path:string){const manuscript=currentManuscript.value;if(!manuscript||path===manuscript.main_file)return store.notify('主文档不能删除，请先切换主文档','error');if(!confirm(`删除项目文件 ${path}？删除会在下次保存版本后生效。`))return;delete manuscript.files[path];selectedFilePath.value=manuscript.main_file}
function setMainFile(path:string){if(!currentManuscript.value||!path.endsWith('.tex'))return;currentManuscript.value.main_file=path;currentManuscript.value.content=currentManuscript.value.files[path].content;selectedFilePath.value=path}
async function exportProject(){const manuscript=currentManuscript.value;if(!manuscript)return;const blob=await api.blob(`/research-projects/${projectId.value}/manuscripts/${manuscript.id}/export`,{});downloadBlob(blob,`${manuscript.title}-v${manuscript.version}.zip`)}
function downloadBlob(blob:Blob,name:string){const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=name;link.click();URL.revokeObjectURL(url)}
async function showVersionDiff(version:number){const manuscript=currentManuscript.value;if(!manuscript)return;const result=await api.get<Entity>(`/research-projects/${projectId.value}/manuscripts/${manuscript.id}/versions/${version}/diff?file_path=${encodeURIComponent(selectedFilePath.value)}`);versionDiff.value=result.diff||'该文件与当前版本没有差异。'}
function captureSelection(){const editor=latexEditor.value;if(!editor)return;const before=editor.value.slice(0,editor.selectionStart);const selected=editor.value.slice(editor.selectionStart,editor.selectionEnd);commentForm.line_start=before.split('\n').length;commentForm.line_end=commentForm.line_start+(selected.match(/\n/g)||[]).length;commentForm.quote=selected}
async function addComment(){if(!currentManuscript.value)return; const item=await api.post<Entity>(`/research-projects/${projectId.value}/comments`,{manuscript_id:currentManuscript.value.id,file_path:selectedFilePath.value,anchored_version:currentManuscript.value.version,...commentForm});comments.value.unshift(item);commentForm.content='';commentForm.quote=''}
async function resolveComment(item:Entity){item.status='resolved';await api.patch(`/research-projects/${projectId.value}/comments/${item.id}`,{status:'resolved'})}
async function compilePdf(){if(!currentManuscript.value)return;const missing=preview.value?.missing_resources||[];if(missing.length){store.notify(`无法完整编译：请先添加 ${missing.length} 个缺失资源（${missing.slice(0,3).join('、')}${missing.length>3?' 等':''}）并保存版本`,'error');return}compiling.value=true;try{const blob=await api.blob(`/research-projects/${projectId.value}/manuscripts/${currentManuscript.value.id}/compile`,{});downloadBlob(blob,`${currentManuscript.value.title}-v${currentManuscript.value.version}.pdf`);store.notify('PDF 编译完成')}catch(error:any){store.notify(error.message,'error')}finally{compiling.value=false}}
async function assistWriting(){const manuscript=currentManuscript.value;if(!manuscript)return;thinking.value=true;try{writingAssistant.value=(await api.post<Entity>(`/research-projects/${projectId.value}/manuscripts/${manuscript.id}/assist`,{task:assistTask.value,selection:'',instruction:assistInstruction.value,agent_id:moduleAgentIds.writing||null})).content}catch(error:any){store.notify(error.message,'error')}finally{thinking.value=false}}
async function restoreVersion(version:number){const manuscript=currentManuscript.value;if(!manuscript||!confirm(`将 v${version} 恢复为一个新的当前版本，是否继续？`))return;currentManuscript.value=await api.post(`/research-projects/${projectId.value}/manuscripts/${manuscript.id}/restore`,{version,base_version:manuscript.version});await selectManuscript(manuscript.id)}
async function updateReviewItem(item:Entity,status:string){item.status=status;await api.patch(`/research-projects/${projectId.value}/reviews/items/${item.id}`,{status,response:item.response||''})}
async function runReview(){if(!selectedManuscriptId.value)return store.notify('请先选择论文','error');if(!reviewRoles.value.length)return store.notify('请至少选择一名独立审稿人','error');reviewRunning.value=true;thinking.value=true;reviewStage.value='委员会正在初始化';reviewProgress.value=reviewRoles.value.map(role=>({role,name:reviewRoleCatalog[role]?.name,status:'queued',progress:0}));try{await api.streamEvents(`/research-projects/${projectId.value}/reviews/stream`,{manuscript_id:selectedManuscriptId.value,roles:reviewRoles.value,...reviewConfig,agent_ids:{chair:moduleAgentIds.review||''}},event=>{if(event.type==='committee_started')reviewStage.value=`委员会已启动，共 ${event.total} 名委员`;if(event.type==='reviewer_started'){const item=reviewProgress.value.find(entry=>entry.role===event.role);if(item){item.status='running';item.progress=35}reviewStage.value=`${event.role_name}正在独立审稿`};if(event.type==='reviewer_completed'){const item=reviewProgress.value.find(entry=>entry.role===event.role);if(item){Object.assign(item,{status:'completed',progress:100,decision:event.decision,confidence:event.confidence,scores:event.scores})}reviewStage.value=`已完成 ${event.completed}/${event.total} 份独立评议`};if(event.type==='committee_completed')reviewStage.value='委员会正在量化汇总分歧与结论';if(event.type==='review_result'){reviews.value.unshift(event.review);reviewStage.value='审稿与委员会汇总已完成'};if(event.type==='error')throw new Error(event.message)});await loadProject();store.notify('独立审稿与委员会汇总已完成')}catch(error:any){store.notify(error.message,'error');reviewStage.value='审稿运行失败'}finally{thinking.value=false;reviewRunning.value=false}}
function switchTab(id:string){router.push(id==='overview'?`/research/${projectId.value}`:`/research/${projectId.value}/${id}`)}
watch(tab,async()=>{await loadSection();await heartbeat()}); watch(()=>[currentManuscript.value?.files,currentManuscript.value?.main_file],()=>{if(currentManuscript.value)preview.value={...researchLatexPreview(flattenClientLatex(currentManuscript.value.files||{},currentManuscript.value.main_file||'main.tex'))}},{flush:'post',deep:true})
function flattenClientLatex(files:Record<string,Entity>,path:string,seen=new Set<string>()):string{if(seen.has(path))return `% 循环引用 ${path}`;seen.add(path);const parent=path.includes('/')?path.slice(0,path.lastIndexOf('/')+1):'';return String(files[path]?.content||'').replace(/\\(?:input|include)\s*\{([^}]+)\}/g,(raw,target)=>{let child=parent+String(target).trim();if(!/\.[a-z]+$/i.test(child))child+='.tex';return files[child]?flattenClientLatex(files,child,seen):raw})}
function researchLatexPreview(content:string){
  const files=currentManuscript.value?.files||{}
  const title=content.match(/\\title\{([^}]*)\}/)?.[1]||'未命名论文'
  const abstract=content.match(/\\begin\{abstract\}([\s\S]*?)\\end\{abstract\}/)?.[1]?.trim()||''
  const authors=[...content.matchAll(/\\author(?:\[[^\]]*\])?\{([^}]*)\}/g)].map(match=>match[1].replace(/\\corref\{[^}]*\}/g,'').trim())
  const keywordBody=content.match(/\\begin\{keyword\}([\s\S]*?)\\end\{keyword\}/)?.[1]||''
  const keywords=keywordBody.split(/\\sep|[,;；]/).map(item=>item.trim()).filter(Boolean)
  const regex=/\\(section|subsection|subsubsection)\*?\{([^}]*)\}/g
  const matches=[...content.matchAll(regex)]
  const sections=matches.map((match,index)=>({
    level:match[1],title:match[2],
    content:content.slice((match.index||0)+match[0].length,matches[index+1]?.index||content.length).replace(/(^|[^\\])%.*$/gm,'$1').trim(),
  }))
  const warnings=[] as string[]
  if((content.match(/\{/g)||[]).length!==(content.match(/\}/g)||[]).length)warnings.push('花括号数量不一致')
  if(!content.includes('\\begin{document}'))warnings.push('缺少 \\begin{document}')
  const graphics=[...content.matchAll(/\\includegraphics(?:\[[^\]]*\])?\{([^}]+)\}/g)].map(match=>match[1].replace(/^\.\//,''))
  const missingGraphics=graphics.filter(path=>!files[path]&&!Object.keys(files).some(key=>key.replace(/\.[^.]+$/,'')===path.replace(/\.[^.]+$/,'')))
  if(missingGraphics.length)warnings.push(`缺少 ${missingGraphics.length} 个图片资源：${missingGraphics.slice(0,3).join('、')}${missingGraphics.length>3?' 等':''}`)
  const bibliographies=[...content.matchAll(/\\bibliography\{([^}]+)\}/g)].flatMap(match=>match[1].split(',').map(name=>name.trim()+'.bib'))
  const missingBibliographies=bibliographies.filter(path=>!files[path])
  if(missingBibliographies.length)warnings.push(`缺少参考文献文件：${missingBibliographies.join('、')}`)
  const assets:Record<string,string>={}
  for(const [path,rawFile] of Object.entries(files)){const file=rawFile as Entity;if(file.encoding==='base64'&&String(file.mime||'').startsWith('image/'))assets[path]=`data:${file.mime};base64,${file.content}`}
  return{title,authors,abstract,keywords,sections,citations:[...new Set([...content.matchAll(/\\cite\w*\{([^}]*)\}/g)].flatMap(match=>match[1].split(',').map(key=>key.trim())))],warnings,assets,missing_resources:[...missingGraphics,...missingBibliographies]}
}
function setPreviewZoom(value:number){previewZoom.value=Math.min(1.8,Math.max(.5,Math.round(value*10)/10))}
function openPreviewImage(payload:{src:string,alt:string}){Object.assign(imageViewer,{show:true,src:payload.src,alt:payload.alt,zoom:1,rotation:0,fit:true})}
function imageZoom(value:number){imageViewer.zoom=Math.min(5,Math.max(.2,Math.round(value*10)/10));imageViewer.fit=false}
function resetImageViewer(){Object.assign(imageViewer,{zoom:1,rotation:0,fit:true})}
onMounted(async()=>{await loadProject();await loadModuleCatalog();await loadSection();await heartbeat();presenceTimer=window.setInterval(heartbeat,30000)});onBeforeUnmount(()=>window.clearInterval(presenceTimer))
</script>

<template>
  <div class="research-project">
    <PageHeader eyebrow="RESEARCH PROJECT" :title="project.name || '科研项目'" :description="project.research_question || project.description">
      <template #actions><div class="presence-row"><span v-for="item in presence" :key="item.id" :title="`${item.display_name} · ${item.page}`">{{ item.display_name?.slice(0,1) }}</span></div><button class="btn" @click="openResources"><Boxes :size="14"/>项目资源</button><button class="btn" @click="openMembers"><Users :size="14"/>协作成员</button></template>
    </PageHeader>
    <nav class="research-tabs"><button v-for="item in tabs" :key="item.id" :class="{active:tab===item.id}" @click="switchTab(item.id)"><component :is="item.icon" :size="15"/>{{ item.label }}</button></nav>
    <section v-if="tab!=='overview'" class="module-expert-bar">
      <div class="expert-identity"><Bot/><span><b>{{ moduleLabels[tab] }}专家</b><small>{{ selectedModuleAgent?.name || '请选择 Agent 工厂中的专家' }}</small></span><i>{{ selectedModuleAgent?.status || '未配置' }}</i></div>
      <select v-model="moduleAgentIds[tab]" class="select" @change="saveModuleAssignments"><option value="">选择模块 Agent</option><option v-for="item in agents.filter(entry=>entry.status!=='archived')" :key="item.id" :value="item.id">{{ item.name }}</option></select>
      <select v-model="moduleWorkflowIds[tab]" class="select" @change="saveModuleAssignments"><option value="">可选：调用已有工作流</option><option v-for="item in workflows" :key="item.id" :value="item.id">{{ item.name }}</option></select>
      <input v-model="moduleAgentPrompts[tab]" class="input" :placeholder="`${moduleLabels[tab]}任务说明`">
      <button class="btn" :disabled="moduleAgentRunning||!moduleAgentIds[tab]" @click="runModuleAgent"><Sparkles/>{{ moduleAgentRunning?'Agent 执行中':'询问专家' }}</button>
      <button class="btn" :disabled="moduleWorkflowRunning||!moduleWorkflowIds[tab]" @click="runModuleWorkflow"><GitBranch/>{{ moduleWorkflowRunning?'工作流运行中':'运行工作流' }}</button>
      <button class="icon-link" title="打开 Agent 工厂" @click="router.push('/agents')"><Bot/></button><button class="icon-link" title="打开工作流页面" @click="router.push('/workflows')"><ExternalLink/></button>
      <div v-if="moduleRunStatus||moduleRunResult" class="module-run-output"><b>{{ moduleRunStatus }}</b><RichAgentMessage v-if="moduleRunResult" :content="String(moduleRunResult)"/></div>
    </section>

    <section v-if="tab==='overview'" class="project-overview">
      <article class="project-question"><span>核心研究问题</span><h2>{{ project.research_question || '尚未定义' }}</h2><p>{{ project.description }}</p></article>
      <div class="overview-metrics"><article><BookOpen/><strong>{{ project.counts?.literature||0 }}</strong><span>项目文献</span></article><article><Lightbulb/><strong>{{ project.counts?.ideas||0 }}</strong><span>研究 Idea</span></article><article><FlaskConical/><strong>{{ project.counts?.experiments||0 }}</strong><span>实验记录</span></article><article><FileCode2/><strong>{{ project.counts?.manuscripts||0 }}</strong><span>论文稿件</span></article><article><ScanSearch/><strong>{{ project.counts?.reviews||0 }}</strong><span>审稿轮次</span></article></div>
      <section class="research-path"><h3>科研推进路径</h3><div><button v-for="item in tabs.slice(1)" :key="item.id" @click="switchTab(item.id)"><component :is="item.icon"/><strong>{{ item.label }}</strong><span>进入模块继续推进</span></button></div></section>
    </section>

    <section v-else-if="tab==='literature'" class="module-grid literature-module">
      <aside class="module-panel"><h3><Search/>智能文献工作流</h3><div class="field"><label>研究主题或检索任务</label><textarea v-model="searchForm.query" class="textarea" placeholder="描述研究对象、主题、重点和纳入要求"></textarea></div><div class="inline-fields"><div class="field"><label>目标数量</label><input v-model.number="searchForm.target_count" type="number" class="input"></div><div class="field"><label>起始年份</label><input v-model.number="searchForm.year_from" type="number" class="input"></div><div class="field"><label>截止年份</label><input v-model.number="searchForm.year_to" type="number" class="input"></div></div><button class="btn btn-primary full-btn" :disabled="thinking" @click="searchLiterature"><WandSparkles :size="14"/>{{ thinking?'正在检索…':'联网调研文献' }}</button><button class="btn full-btn" :disabled="thinking" @click="synthesize"><Sparkles :size="14"/>生成综述与研究脉络</button><button class="btn full-btn" :disabled="thinking" @click="generateAcademicFigure"><ScanSearch :size="14"/>生成学术脉络图</button><AcademicGraph :figure="academicFigure"/><RichAgentMessage v-if="synthesis" :content="synthesis"/></aside>
      <main class="literature-list"><header><div><h3>项目文献集合</h3><p>候选文献必须由成员确认后，才进入综述和论文证据范围。</p></div><b>{{ literature.length }} 篇</b></header><article v-for="item in literature" :key="item.id"><div class="credibility">{{ item.credibility }}<small>可信度</small></div><div class="literature-copy"><span>{{ item.source }} · {{ item.year||'年份未知' }} · {{ item.doi||'无 DOI' }}</span><h4>{{ item.title }}</h4><p>{{ item.abstract||'尚未取得摘要，请人工核验原文。' }}</p><footer><button :class="{active:item.status==='included'}" @click="setLiteratureStatus(item,'included')">纳入</button><button :class="{active:item.status==='priority'}" @click="setLiteratureStatus(item,'priority')">重点</button><button :class="{danger:item.status==='excluded'}" @click="setLiteratureStatus(item,'excluded')">排除</button><a v-if="item.url" :href="item.url" target="_blank">核验来源</a></footer></div></article></main>
    </section>

    <section v-else-if="tab==='frontier'" class="frontier-layout">
      <aside class="frontier-control">
        <h3><ScanSearch/>领域前沿追踪</h3><p>检索近期论文并形成项目内热点、增长主题与时间趋势。每个判断都可回到题录来源。</p>
        <div class="field"><label>跟踪主题</label><textarea v-model="frontierForm.query" class="textarea" :placeholder="project.research_question||'输入需要持续追踪的研究主题'"/></div>
        <div class="inline-fields"><div class="field"><label>时间窗（年）</label><input v-model.number="frontierForm.recent_years" class="input" type="number" min="1" max="15"></div><div class="field"><label>目标文献数</label><input v-model.number="frontierForm.target_count" class="input" type="number" min="3" max="80"></div></div>
        <label class="refresh-choice"><input v-model="frontierForm.refresh" type="checkbox">先联网更新近期题录；不可用时使用项目已有文献</label>
        <button class="btn btn-primary full-btn" :disabled="frontierBusy" @click="trackFrontier"><ScanSearch/>{{ frontierBusy?'正在检索与归纳…':'生成最新前沿快照' }}</button>
        <section v-if="frontierSnapshot" class="frontier-summary"><strong>证据范围</strong><p>{{ frontierSnapshot.summary }}</p><small>{{ frontierSnapshot.methodology }}</small><div v-if="frontierSnapshot.refresh?.error">联网更新未完成：{{ frontierSnapshot.refresh.error }}；当前结果来自本地题录。</div></section>
        <section v-if="frontierSnapshots.length" class="snapshot-history"><strong>历史快照</strong><button v-for="item in frontierSnapshots" :key="item.id" @click="frontierSnapshot=item.payload"><span>{{ item.title }}</span><small>{{ new Date(item.created_at).toLocaleString() }} · {{ item.source_ids?.length||0 }} 个来源</small></button></section>
      </aside>
      <main class="frontier-results">
        <template v-if="frontierSnapshot"><div class="frontier-metrics"><article v-for="topic in frontierSnapshot.hot_topics?.slice(0,5)||[]" :key="topic.id"><span>{{ topic.label }}</span><strong>{{ topic.heat }}</strong><small>相对热度 · 增长 {{ topic.growth }}</small></article></div><FrontierGraph :snapshot="frontierSnapshot"/><section class="trend-timeline"><h3>时间趋势</h3><article v-for="item in frontierSnapshot.timeline||[]" :key="item.year"><b>{{ item.year }}</b><i><em :style="{width:`${Math.max(4,item.papers/Math.max(1,...frontierSnapshot.timeline.map((entry:Entity)=>entry.papers))*100)}%`}"/></i><span>{{ item.papers }} 篇 · {{ item.top_topics?.join(' / ')||'暂无稳定主题' }}</span></article></section><section class="frontier-sources"><h3>可追溯来源</h3><article v-for="(source,index) in frontierSnapshot.sources||[]" :key="source.id"><b>[{{ index+1 }}]</b><span><strong>{{ source.title }}</strong><small>{{ source.source }} · {{ source.year }} · DOI {{ source.doi||'待核验' }} · 可信度 {{ source.credibility }}</small></span><a v-if="source.url" :href="source.url" target="_blank">原文</a></article></section></template>
        <div v-else class="frontier-empty"><ScanSearch/><strong>还没有领域前沿快照</strong><span>先设置时间窗并生成。趋势仅依据可追溯题录，不会把项目样本夸大为全领域结论。</span></div>
      </main>
    </section>

    <section v-else-if="tab==='ideas'" class="idea-layout">
      <main class="idea-chat"><header><Lightbulb/><div><h3>Idea 苏格拉底对话</h3><p>系统每轮只追问一个关键问题，逐步检查新颖性、可证伪性和实验可行性。</p></div></header><div class="idea-messages"><article v-for="(message,index) in ideaMessages" :key="index" :class="message.role"><strong>{{ message.role==='user'?'你':'Idea 导师' }}</strong><RichAgentMessage :content="message.content"/></article><div v-if="!ideaMessages.length" class="chat-empty"><Sparkles/><strong>从一个模糊想法开始也可以</strong><span>例如：我想研究大模型代码反馈是否真的改善学生的调试能力。</span></div></div><footer><textarea v-model="ideaInput" @keydown.ctrl.enter.prevent="sendIdea" placeholder="描述想法、疑问或约束；Ctrl + Enter 发送"></textarea><button @click="sendIdea"><Send/></button></footer></main>
      <aside class="idea-canvas"><header><div><h3>Idea 卡片</h3><small>{{ ideas.length }} 个已保存想法</small></div><button class="btn btn-primary" @click="resetIdeaForm();ideaPanelMode='edit';showIdeaPanel=true"><Plus/>新建 Idea</button></header><div class="idea-cards"><article v-for="item in ideas" :key="item.id"><header><span>{{ item.status }}</span><nav><button title="查看详情" @click="openIdea(item,'view')"><Eye/></button><button title="修改" @click="openIdea(item,'edit')"><Pencil/></button><button title="删除" :disabled="item.status==='adopted'" @click="deleteIdea(item)"><Trash2/></button></nav></header><strong>{{ item.title }}</strong><p>{{ item.hypothesis||item.problem||'尚未填写研究假设' }}</p><footer><button class="btn" @click="openIdea(item,'view')">查看完整卡片</button><button v-if="item.status!=='adopted'" class="btn" @click="adoptIdea(item)"><FlaskConical/>转为实验</button></footer></article><div v-if="!ideas.length" class="idea-empty"><Lightbulb/><strong>还没有 Idea 卡片</strong><span>从苏格拉底对话中提炼想法，或直接新建。</span></div></div></aside>
    </section>

    <section v-else-if="tab==='assets'" class="assets-layout">
      <div class="asset-column"><header><div><h3>项目科研记忆</h3><p>每条记忆保留类型、来源、置信度和锁定状态。</p></div><button class="btn" @click="createSkill"><ShieldCheck :size="14"/>从锁定记忆生成 Skill</button></header><div class="memory-create"><select v-model="memoryForm.category" class="select"><option value="decision">研究决策</option><option value="hypothesis">研究假设</option><option value="evidence">文献证据</option><option value="method">方法规则</option><option value="constraint">实验约束</option><option value="failure">失败经验</option><option value="writing">写作规范</option></select><textarea v-model="memoryForm.content" class="textarea" placeholder="记录经过确认、下一阶段需要继续使用的内容"></textarea><label><input v-model="memoryForm.locked" type="checkbox">锁定为项目共识</label><button class="btn btn-primary" @click="saveMemory">保存记忆</button></div><div class="memory-list"><article v-for="item in memories" :key="item.id" :class="{locked:item.locked}"><b>{{ item.category }}</b><p>{{ item.content }}</p><footer>{{ item.source_type }} · 置信度 {{ Math.round(item.confidence*100) }}%<span v-if="item.locked">已锁定</span></footer></article></div></div>
      <div class="asset-column"><header><div><h3>实验承接</h3><p>将 Idea 转换为可证伪、可复现的实验计划。</p></div></header><div class="experiment-create"><div class="field"><label>实验名称</label><input v-model="experimentForm.title" class="input"></div><div class="field"><label>实验目标</label><textarea v-model="experimentForm.objective" class="textarea"></textarea></div><div class="field"><label>假设</label><textarea v-model="experimentForm.hypothesis" class="textarea"></textarea></div><div class="inline-fields"><div class="field"><label>数据集</label><input v-model="experimentForm.design.dataset" class="input"></div><div class="field"><label>指标</label><input v-model="experimentForm.design.metrics" class="input"></div></div><div class="inline-fields"><div class="field"><label>基线</label><input v-model="experimentForm.design.baselines" class="input"></div><div class="field"><label>随机种子</label><input v-model="experimentForm.design.random_seed" class="input"></div></div><button class="btn btn-primary full-btn" @click="saveExperiment"><Plus :size="14"/>创建实验方案</button></div><div class="experiment-list"><article v-for="item in experiments" :key="item.id"><FlaskConical/><div><strong>{{ item.title }}</strong><p>{{ item.objective }}</p><select v-model="item.status" class="select"><option value="planned">计划中</option><option value="running">运行中</option><option value="completed">已完成</option><option value="failed">失败</option></select><textarea v-model="item.result.notes" class="textarea" placeholder="记录指标、异常、统计结果和结论"></textarea><button class="btn" @click="updateExperiment(item)">保存实验记录</button></div></article></div></div>
    </section>

    <section v-else-if="tab==='data'" class="data-layout">
      <aside class="data-sidebar">
        <h3><Boxes/>科研数据资产</h3><p>支持 CSV、TSV、JSON，先做数据画像和质量检查，再生成图表。</p><button class="btn btn-primary full-btn" :disabled="dataBusy" @click="dataInput?.click()"><Upload/>{{ dataBusy?'正在分析…':'导入科研数据' }}</button><input ref="dataInput" hidden type="file" accept=".csv,.tsv,.json" @change="uploadDataset">
        <div class="dataset-list"><button v-for="item in datasets" :key="item.id" :class="{active:selectedDatasetId===item.id}" @click="selectedDatasetId=item.id"><Boxes/><span><strong>{{ item.title }}</strong><small>{{ item.payload.profile?.rows }} 行 · {{ item.payload.fields?.length }} 字段</small></span><i title="删除" @click.stop="deleteDataAsset(item)"><Trash2/></i></button></div>
        <section class="figure-history" v-if="publicationFigures.length"><strong>已生成图表</strong><button v-for="item in publicationFigures" :key="item.id" @click="figureResult={id:item.id,title:item.title,...item.payload}"><span>{{ item.title }}</span><small>{{ item.metadata?.chart_type }} · {{ item.metadata?.journal }}</small></button></section>
      </aside>
      <main class="data-workbench">
        <template v-if="selectedDataset"><section class="data-profile"><header><div><h3>{{ selectedDataset.title }}</h3><p>自动画像只描述导入数据，不替代研究设计、显著性检验或因果识别。</p></div><b>{{ selectedDataset.payload.profile?.rows }} × {{ selectedDataset.payload.fields?.length }}</b></header><div class="insight-list"><article v-for="item in selectedDataset.payload.insights||[]" :key="item"><Sparkles/><span>{{ item }}</span></article><article v-for="item in selectedDataset.payload.quality_warnings||[]" :key="item" class="warning"><ShieldCheck/><span>{{ item }}</span></article></div><div class="column-profile"><article v-for="column in selectedDataset.payload.profile?.columns||[]" :key="column.name"><header><strong>{{ column.name }}</strong><span>{{ column.type }}</span></header><p>缺失 {{ column.missing_rate }}% · 唯一值 {{ column.unique }}</p><small v-if="column.type==='numeric'">均值 {{ column.mean }} · 中位数 {{ column.median }} · SD {{ column.sd }}</small><small v-else>{{ column.top_values?.slice(0,3).map((entry:Entity)=>`${entry.value}(${entry.count})`).join('、') }}</small></article></div></section>
          <section class="figure-builder"><header><div><h3>SciPilot 论文图表工作台</h3><p>数据画像 → 论证目标 → 图型选择 → 期刊规范 → 视觉自检 → 矢量导出。</p></div></header><div class="figure-fields"><label>图表要支持的论点<textarea v-model="figureForm.argument" class="textarea"/></label><label>图型<select v-model="figureForm.chart_type" class="select"><option value="auto">由数据和论点自动选择</option><option value="strip">分组原始点图</option><option value="scatter">散点图</option><option value="correlation">相关性热力图</option><option value="histogram">直方图</option><option value="bar">分类频数图</option><option value="pie">饼图（将触发质量门禁）</option><option value="3d">3D 图（将触发质量门禁）</option></select></label><label>X / 分类变量<select v-model="figureForm.x" class="select"><option value="">自动</option><option v-for="field in selectedDataset.payload.fields" :key="field" :value="field">{{ field }}</option></select></label><label>Y / 数值变量<select v-model="figureForm.y" class="select"><option value="">自动</option><option v-for="field in selectedDataset.payload.profile?.numeric_fields||[]" :key="field" :value="field">{{ field }}</option></select></label><label>目标期刊<select v-model="figureForm.journal" class="select"><option value="general">通用学术规范</option><option value="nature">Nature</option><option value="science">Science</option><option value="ieee">IEEE</option><option value="elsevier">Elsevier</option><option value="pnas">PNAS</option><option value="chinese_core">中文核心</option></select></label><label>图题<input v-model="figureForm.title" class="input" placeholder="简洁陈述图中事实"></label><button class="btn btn-primary" :disabled="dataBusy" @click="generatePublicationFigure"><WandSparkles/>{{ dataBusy?'正在绘制与自检…':'生成论文图表' }}</button></div></section>
          <PublicationFigure v-if="figureResult" :figure="figureResult" @download="downloadFigure"/>
        </template><div v-else class="frontier-empty"><Boxes/><strong>导入一个科研数据集</strong><span>系统将在本地完成字段识别、缺失率、描述统计、相关性、洞察边界和论文图表建议。</span></div>
      </main>
    </section>

    <section v-else-if="tab==='writing'" class="writing-layout">
      <div class="native-import-bar"><strong>项目导入</strong><button @click="pickNativeProject(false)"><Upload/>原生选择 ZIP / 多文件</button><button @click="pickNativeProject(true)"><FolderOpen/>原生选择文件夹</button><button :disabled="!currentManuscript" @click="addNativeResources"><FilePlus2/>向当前论文添加图片 / .bib</button><span>文件夹、图片和 BibTeX 均保留项目内相对路径</span></div>
      <aside class="manuscript-list"><header><h3>论文稿件</h3></header><div class="new-manuscript"><input v-model="manuscriptForm.title" class="input" placeholder="新论文标题"><button @click="createManuscript"><Plus/></button></div><div class="import-actions"><button @click="importInput?.click()"><Upload/>导入 ZIP / 文件</button><button @click="folderInput?.click()"><FolderOpen/>导入文件夹</button><input ref="importInput" hidden type="file" multiple accept=".zip,.tex,.bib,.cls,.sty,.bst,.png,.jpg,.jpeg,.pdf,.eps,.svg,.csv" @change="importManuscript($event,false)"><input ref="folderInput" hidden type="file" multiple webkitdirectory @change="importManuscript($event,true)"></div><small v-if="importing" class="importing">正在安全解析 LaTeX 项目…</small><button v-for="item in manuscripts" :key="item.id" :class="{active:selectedManuscriptId===item.id}" @click="selectManuscript(item.id)"><FileCode2/><span><strong>{{ item.title }}</strong><small>LaTeX · v{{ item.version }}</small></span></button><section><h4><Sparkles/>AI 写作助手</h4><select v-model="assistTask" class="select"><option value="outline">生成论文提纲</option><option value="polish">语言润色</option><option value="logic">逻辑与论证检查</option><option value="citation_check">引用完整性检查</option><option value="academic_style">学术化改写</option><option value="translate">中英学术互译</option><option value="response_letter">审稿回复信</option></select><textarea v-model="assistInstruction" class="textarea" placeholder="可选：目标期刊、篇幅或修改要求"></textarea><button class="btn btn-primary full-btn" :disabled="thinking" @click="assistWriting">{{ thinking?'分析中…':'生成建议' }}</button><div v-if="writingAssistant" class="assistant-result"><RichAgentMessage :content="writingAssistant"/></div></section><section><h4><History/>版本记录</h4><article v-for="item in versions" :key="item.id"><b>v{{ item.version }}</b><span>{{ item.author_name }}<small>{{ item.change_summary }}</small></span><button v-if="currentManuscript&&item.version!==currentManuscript.version" title="比较当前文件" @click="showVersionDiff(item.version)"><GitCompare/></button><button v-if="currentManuscript&&item.version!==currentManuscript.version" @click="restoreVersion(item.version)">恢复</button></article></section></aside>
      <main v-if="currentManuscript" class="latex-editor"><header><div><strong>{{ currentManuscript.title }}</strong><span>协作版本 v{{ currentManuscript.version }} · 主文档 {{ currentManuscript.main_file }}</span></div><input v-model="saveSummary" placeholder="本次修改说明"><button class="btn" @click="exportProject"><Archive :size="14"/>ZIP</button><button class="btn" @click="compilePdf"><Download :size="14"/>{{ compiling?'编译中':'PDF' }}</button><button class="btn btn-primary" :disabled="!canEdit" @click="saveManuscript"><Save :size="14"/>保存版本</button></header><div class="project-workspace"><aside class="file-tree"><header><b>项目文件</b><button title="新建文件" @click="addProjectFile"><FilePlus2/></button></header><button v-for="([path]) in fileEntries" :key="path" :class="{active:selectedFilePath===path}" @click="selectedFilePath=path"><FileCode2/><span>{{ path }}</span><Star v-if="path===currentManuscript.main_file" class="main-star"/><button v-else-if="path.endsWith('.tex')" title="设为主文档" @click.stop="setMainFile(path)"><Star/></button><button title="删除文件" @click.stop="deleteProjectFile(path)"><Trash2/></button></button></aside><section class="source-editor"><div class="file-toolbar"><strong>{{ selectedFilePath }}</strong><span>{{ activeFile?.encoding==='base64'?'二进制资源':`${activeFile?.size||0} bytes` }}</span></div><textarea v-if="editableFile" ref="latexEditor" v-model="activeFileContent" spellcheck="false" @select="captureSelection"></textarea><div v-else class="binary-preview"><FileCode2/><strong>二进制项目资源</strong><span>{{ activeFile?.mime }} · {{ activeFile?.size }} bytes</span><p>该资源会参与 ZIP 导出和本地 LaTeX 编译，但不在文本编辑器中直接修改。</p></div></section></div><pre v-if="versionDiff" class="version-diff">{{ versionDiff }}</pre></main>
      <section v-if="currentManuscript" class="writing-preview" :class="{fullscreen:previewFullscreen}"><header><div><strong>即时渲染</strong><span>多文件展开 · 图片点击放大 · KaTeX 结构预览</span></div><nav class="preview-tools"><button title="缩小" @click="setPreviewZoom(previewZoom-.1)"><ZoomOut/></button><b>{{ Math.round(previewZoom*100) }}%</b><button title="放大" @click="setPreviewZoom(previewZoom+.1)"><ZoomIn/></button><button title="适合宽度" @click="setPreviewZoom(.8)">适宽</button><button title="实际大小" @click="setPreviewZoom(1)">1:1</button><button :title="previewFullscreen?'退出全屏':'全屏预览'" @click="previewFullscreen=!previewFullscreen"><component :is="previewFullscreen?X:Maximize2"/></button></nav></header><div class="preview-scroll"><LatexPreview :preview="preview" :zoom="previewZoom" @image-open="openPreviewImage"/></div><aside class="comment-panel"><h3><MessageSquarePlus/>协作批注</h3><div class="comment-context">{{ selectedFilePath }} · v{{ currentManuscript.version }} · 选中文本可自动定位行号</div><div class="comment-form"><span>行 <input v-model.number="commentForm.line_start" type="number"> 至 <input v-model.number="commentForm.line_end" type="number"></span><textarea v-model="commentForm.content" placeholder="提出修改意见、疑问或批改建议"></textarea><button :disabled="!canReview||!editableFile" @click="addComment">提交批注</button></div><article v-for="item in comments" :key="item.id" :class="{resolved:item.status==='resolved'}"><header><strong>{{ item.author_name }}</strong><span>{{ item.file_path }} · v{{ item.anchored_version }} · L{{ item.line_start||'?' }}–{{ item.line_end||'?' }}</span></header><blockquote v-if="item.quote">{{ item.quote }}</blockquote><p>{{ item.content }}</p><button v-if="item.status==='open'&&canEdit" @click="resolveComment(item)">标记已解决</button></article></aside></section>
      <section v-else class="writing-empty"><FileCode2/><strong>创建或导入一篇 LaTeX 论文</strong><span>支持项目 ZIP、多个文件或整个文件夹；导入后可多文件编辑、即时渲染、版本比较和协作批注。</span><button class="btn btn-primary" @click="importInput?.click()"><Upload/>导入 LaTeX 项目</button></section>
    </section>

    <section v-else-if="tab==='review'" class="review-layout">
      <aside class="review-config"><h3><ScanSearch/>模拟审稿委员会</h3><div class="field"><label>选择稿件</label><select v-model="selectedManuscriptId" class="select" @change="selectManuscript(selectedManuscriptId)"><option v-for="item in manuscripts" :key="item.id" :value="item.id">{{ item.title }} · v{{ item.version }}</option></select></div><div class="field"><label>目标期刊 / 会议</label><input v-model="reviewConfig.venue" class="input" placeholder="例如：CCF-A 类计算机会议"></div><div class="field"><label>审稿严格度</label><select v-model="reviewConfig.rigor" class="select"><option value="standard">标准评审</option><option value="strict">严格评审</option><option value="top_venue">顶级会议/期刊门槛</option></select></div><div class="field"><label>本轮特别关注</label><textarea v-model="reviewConfig.focus" class="textarea" placeholder="例如：算法复杂度证明、数据泄漏与消融实验"></textarea></div><label v-for="(role,id) in reviewRoleCatalog" :key="id" class="role-check"><input v-model="reviewRoles" type="checkbox" :value="id"><span><b>{{ role.name }}</b><small>{{ role.desc }}</small></span></label><button class="btn btn-primary full-btn" :disabled="reviewRunning||!canReview" @click="runReview"><Sparkles :size="14"/>{{ reviewRunning?'审稿委员会运行中…':'开始精细模拟审稿' }}</button></aside>
      <aside class="review-live"><header><div><Bot/><span><b>委员 Agent 实时进度</b><small>{{ selectedModuleAgent?.name||'模拟同行评审委员会主席' }}</small></span></div><i :class="{running:reviewRunning}">{{ reviewRunning?'运行中':'就绪' }}</i></header><div class="review-stage">{{ reviewStage }}</div><article v-for="item in reviewProgress" :key="item.role" :class="item.status"><span class="reviewer-avatar">{{ item.name?.slice(0,1) }}</span><div><b>{{ item.name }}</b><small>{{ item.status==='queued'?'等待独立审稿':item.status==='running'?'正在阅读与量化评估':`已完成 · ${item.decision||''}` }}</small><em><i :style="{width:`${item.progress}%`}"/></em></div><strong>{{ item.progress }}%</strong></article><div v-if="!reviewProgress.length" class="live-empty"><Users/><span>选择审稿委员并开始后，这里将实时展示每名委员的启动、阅读、评分和完成状态。</span></div></aside>
      <main class="review-results"><article v-for="review in reviews" :key="review.id" class="review-report"><header><div><span>第 {{ review.round }} 轮 · 稿件 v{{ review.report?.manuscript_version }} · {{ review.report?.venue }}</span><h3>{{ ({accept:'接收',minor_revision:'小修',major_revision:'大修',reject:'拒稿'} as any)[review.decision]||review.decision }}</h3></div><div class="score-row"><b v-for="(score,key) in review.scores" :key="key">{{ key }} {{ score }}</b></div></header><section v-if="review.report?.committee" class="committee-summary"><p>{{ review.report.committee.summary }}</p><div><span>主要问题 {{ review.report.committee.major_issues }}</span><span>次要问题 {{ review.report.committee.minor_issues }}</span><span>委员分歧 {{ review.report.committee.disagreement }}</span><span>录用阈值 {{ review.report.committee.decision_threshold }}</span></div></section><details v-for="member in review.report?.reviewer_reports||[]" :key="member.role" class="reviewer-detail"><summary>{{ member.role_name }} · 置信度 {{ Math.round(member.confidence*100) }}% · {{ member.decision }}</summary><p>{{ member.summary }}</p><div class="mini-scores"><b v-for="(score,key) in member.scores" :key="key">{{ key }} {{ score }}/10</b></div><strong>优点</strong><ul><li v-for="text in member.strengths" :key="text">{{ text }}</li></ul><strong>不足</strong><ul><li v-for="text in member.weaknesses" :key="text">{{ text }}</li></ul></details><details><summary>评测方法与边界</summary><p>{{ review.report?.methodology?.limitations }}</p></details><section><article v-for="item in review.items" :key="item.id" :class="item.severity"><header><b>{{ item.severity==='major'?'主要问题':'次要问题' }}</b><span>{{ item.reviewer_role }} · {{ item.category }} · {{ item.location }} · 置信度 {{ Math.round((item.confidence||0)*100) }}%</span></header><h4>{{ item.issue }}</h4><p><strong>依据：</strong>{{ item.evidence }}</p><p><strong>建议：</strong>{{ item.suggestion }}</p><textarea v-model="item.response" class="textarea" placeholder="作者逐点回复、修改文件与行号"></textarea><footer><span>{{ item.status }}</span><nav><button @click="updateReviewItem(item,'accepted')">采纳为任务</button><button @click="updateReviewItem(item,'resolved')">标记已解决</button><button @click="updateReviewItem(item,'rejected')">不采纳</button></nav></footer></article></section></article><div v-if="!reviews.length" class="review-empty"><ScanSearch/><strong>尚未进行模拟审稿</strong><span>每名委员先独立审稿，再量化汇总分数、分歧、证据与修改任务。</span></div></main>
    </section>

    <FloatingPanel v-model="showMembers" title="项目协作与可信记录" eyebrow="COLLABORATION LEDGER" description="通过邀请码快速加入；成员按角色协作，所有关键写作动作进入前后哈希相连的项目记录链。" size="large"><section class="invite-panel"><h3>邀请协作者</h3><div><select v-model="inviteForm.role" class="select"><option value="manager">项目管理员</option><option value="editor">共同作者 / 编辑者</option><option value="reviewer">审稿者 / 批改者</option><option value="viewer">只读成员</option></select><input v-model.number="inviteForm.expires_hours" class="input" type="number" min="1" max="720" title="有效小时"><input v-model.number="inviteForm.max_uses" class="input" type="number" min="1" max="200" title="可使用次数"><button class="btn btn-primary" :disabled="!canEdit" @click="createInvite">生成邀请码</button></div><div v-if="inviteCode" class="invite-code"><code>{{ inviteCode }}</code><button class="btn" @click="copyInvite">复制</button></div><small>协作者在“科研空间 → 使用邀请码加入”即可进入，无需负责人预先知道用户名。</small></section><div class="member-create"><input v-model="memberForm.username" class="input" placeholder="也可按已注册用户名添加"><select v-model="memberForm.role" class="select"><option value="manager">项目管理员</option><option value="editor">共同作者 / 编辑者</option><option value="reviewer">审稿者 / 批改者</option><option value="viewer">只读成员</option></select><button class="btn" @click="addMember">添加成员</button></div><div class="member-list"><article v-for="item in members" :key="item.id"><span>{{ item.display_name?.slice(0,1) }}</span><div><strong>{{ item.display_name }}</strong><small>@{{ item.username }}</small></div><b>{{ item.role }}</b></article></div><section class="ledger-panel"><header><h3>协作记录链</h3><b :class="{ok:ledger.verified}">{{ ledger.verified?'哈希链校验通过':'记录链异常' }}</b></header><p v-if="ledger.head_hash">链头 {{ ledger.head_hash.slice(0,16) }}…</p><article v-for="item in ledger.entries?.slice(0,12)" :key="item.id"><span>#{{ item.sequence }}</span><div><strong>{{ item.action }}</strong><small>{{ item.actor }} · {{ new Date(item.created_at).toLocaleString() }}</small></div><code>{{ item.entry_hash.slice(0,12) }}…</code></article></section><template #footer><button class="btn" @click="showMembers=false">完成</button></template></FloatingPanel>
    <FloatingPanel v-model="showResources" title="科研项目资源池" eyebrow="PROJECT RESOURCES" description="将系统已有 Agent、专业知识库、智能工作流和已验证 Skill 绑定到本项目；后续检索、实验和写作均可复用这些能力。" size="large"><div class="resource-create"><select v-model="resourceForm.resource_type" class="select" @change="resourceForm.resource_id=''"><option value="agent">Agent</option><option value="knowledge_base">专业知识库</option><option value="workflow">智能工作流</option><option value="skill">已验证 Skill</option></select><select v-model="resourceForm.resource_id" class="select"><option value="">选择系统资源</option><option v-for="item in currentResourceOptions" :key="item.id" :value="item.id">{{ item.name }}</option></select><input v-model="resourceForm.label" class="input" placeholder="项目内别名（可选）"><button class="btn btn-primary" :disabled="!canEdit" @click="addResource"><Plus :size="14"/>绑定资源</button></div><div class="resource-list"><article v-for="item in resources" :key="item.id"><Boxes :size="16"/><div><strong>{{ item.label || item.resource_id }}</strong><small>{{ resourceTypeLabels[item.resource_type] }} · {{ item.resource_id }}</small></div><b>已绑定</b></article><div v-if="!resources.length" class="resource-empty">当前项目尚未绑定系统资源。</div></div><template #footer><button class="btn" @click="showResources=false">完成</button></template></FloatingPanel>
